sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    var fields = api.data.record.form.fields;
    var fieldValues = {};
    var disableRequest = false;
    for (var key in fields) {
        if (fields[key].mandatory && fields[key].value === "") {
            disableRequest = true;
            break;
        }

        if (key != 'valid_to' && key != 'valid_from') {
            fieldValues[key] = {
                "name": fields[key].name,
                "value": fields[key].value,
                "type": fields[key].type,
                "displayValue": fields[key].displayValue
            };
        }
    }

    if (fields.requested_valid_to && fields.valid_to) {
        var validTo = new Date(fields.valid_to.displayValue);
        var requestedValidTo = new Date(fields.requested_valid_to.displayValue);
        if (requestedValidTo <= validTo)
            disableRequest = true;
    }

    api.setState('disableRequest', disableRequest);
    api.setState('updatedFieldValues', fieldValues);
}
